/**
 * Checks that a save from an older FIFA is identified, read and synced into a career.
 *
 *   DATABASE_URL=data/game-versions-test.db npx tsx scripts/test-game-versions.ts
 *
 * IT REFUSES TO RUN AGAINST THE LIVE DATABASE, for the same reason `test-sync.ts` does: this writes a
 * career, a squad, three seasons and a transfer deal. Point `DATABASE_URL` at a copy.
 *
 * WHAT THIS PROVES, AND WHAT IT CANNOT. The save it reads is generated by
 * `scripts/make-fifa18-fixture.ts` in FIFA 18's layout with FIFA 18's own datasheet, so this is
 * evidence about the PARSER: that a save of that generation is identified correctly, that its tables
 * and fields resolve through the right datasheet, that bit-packed records decode to the values that
 * were written, and that the result syncs into the same career shape an FC save produces. It is NOT
 * evidence that EA's FIFA 18 writes what the fixture writes, and the registry marks that game
 * `synthetic` for exactly that reason.
 *
 * The regression half matters as much as the new half: the five datasheets must not change how the
 * app's own FC saves are read, and those are real files, so they are identified here on every run.
 */
import { execFileSync } from "child_process";
import fs from "fs";
import path from "path";
import { eq } from "drizzle-orm";
import { db } from "../src/lib/db/client";
import { careers, players, seasonHistory, transferDeals } from "../src/lib/db/schema";
import { listSaveTableIds } from "../src/lib/parser/feasibility-parser";
import { chooseGameVersion, type MetaIndex } from "../src/lib/parser/game-versions";
import { SyncService } from "../src/lib/sync/sync-service";
import type { SaveCandidate } from "../src/lib/parser/interface";

let passed = 0;
const failures: string[] = [];

function check(label: string, condition: boolean, detail?: string): void {
  if (condition) {
    passed += 1;
    console.log(`  ok   ${label}`);
  } else {
    failures.push(label);
    console.log(`  FAIL ${label}${detail ? ` -> ${detail}` : ""}`);
  }
}

const databaseUrl = process.env.DATABASE_URL ?? "";
if (!databaseUrl.includes("game-versions-test")) {
  console.error(
    "Refusing to run: DATABASE_URL must point at a copy (it must contain 'game-versions-test'),\n" +
      `not ${databaseUrl || "(unset)"}.`
  );
  process.exit(1);
}

const FIXTURE = path.join(process.cwd(), "data", "saves", "Career20180108121239");
const FIXTURE_CLUB = 7788;
const CAREER_ID = `career_club_${FIXTURE_CLUB}`;

/**
 * The whole suite, in one function.
 *
 * Not top-level code: this script is built as CommonJS, where `await` is only legal inside a function.
 * The body below is deliberately left at one level of indentation rather than nested, because it is a
 * single flat sequence of stages and the extra indent would only hide that.
 */
async function main(): Promise<void> {

// ---------------------------------------------------------------------------------------------
console.log("\nthe fixture is generated in FIFA 18's layout, then identified");
// ---------------------------------------------------------------------------------------------

execFileSync("npx", ["tsx", "scripts/make-fifa18-fixture.ts", "--out", FIXTURE], {
  stdio: ["ignore", "ignore", "inherit"],
  shell: true,
});

const bytes = new Uint8Array(fs.readFileSync(FIXTURE));
const index = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), "public", "parse-resources", "meta-index.json"), "utf8")
) as MetaIndex;

const choice = chooseGameVersion(listSaveTableIds(bytes), index);
check("a FIFA 18 save identifies as FIFA 18", choice?.descriptor.id === "FIFA18", choice?.descriptor.id);
check("and it does so confidently", choice?.confident === true, `${choice?.score}`);

// The fixture's own round-trip assertions ran in the generator above; if any value had come back wrong
// that command would have exited non-zero and this suite would have stopped there.

// ---------------------------------------------------------------------------------------------
console.log("\na save from an older FIFA syncs into a career");
// ---------------------------------------------------------------------------------------------

const candidate: SaveCandidate = {
  id: "fixture",
  filePath: FIXTURE,
  fileName: path.basename(FIXTURE),
  lastModified: new Date(),
  fileSizeBytes: bytes.length,
  slotKind: "career",
};

const result = await new SyncService().syncCandidate(candidate);
// A first run writes; a re-run finds the payload hash unchanged and reports NO_CHANGE, which is the
// pipeline's documented idempotence rather than a failure. Both are accepted here, and the second run
// is checked separately below so that "it did nothing" cannot pass as "it worked".
check(
  "the sync either wrote a career or found nothing to change",
  result.status === "SYNCED" || result.status === "NO_CHANGE",
  String(result.status)
);

const career = await db.select().from(careers).where(eq(careers.id, CAREER_ID)).get();
check("a career row exists for the fixture club", career !== undefined);
check(
  "with the manager the save named",
  career?.managerName === "Fixture Manager",
  String(career?.managerName)
);
check("and the club the save named", career?.clubName === "Fixture Athletic", String(career?.clubName));
check(
  "and the in-game date the save carries",
  career?.inGameDate === "2026-11-08",
  String(career?.inGameDate)
);
check("and the season year", career?.currentSeason === 2026, String(career?.currentSeason));

const squad = await db.select().from(players).where(eq(players.careerId, CAREER_ID));
check("three players were written", squad.length === 3, String(squad.length));
const striker = squad.find((player) => player.eaPlayerId === 69957);
check(
  "a player is named from the reference table",
  striker?.name === "J. Elordi",
  String(striker?.name)
);
check("with his rating", striker?.overallRating === 74, String(striker?.overallRating));
check("and his nationality", striker?.nationalityId === 18, String(striker?.nationalityId));

const seasons = await db.select().from(seasonHistory).where(eq(seasonHistory.careerId, CAREER_ID));
check("three seasons were written", seasons.length === 3, String(seasons.length));

const deals = await db.select().from(transferDeals).where(eq(transferDeals.careerId, CAREER_ID));
check("the agreed transfer was written", deals.length === 1, String(deals.length));
check(
  "and it reads as an INCOMING deal, from the club the player was registered to",
  deals[0]?.buyingTeamId === FIXTURE_CLUB && deals[0]?.sellingTeamId === 69,
  `${deals[0]?.buyingTeamId} <- ${deals[0]?.sellingTeamId}`
);

// Re-syncing the same save must add nothing. Asserted plainly because a sync that silently duplicated
// its own rows would still satisfy every check above.
const again = await new SyncService().syncCandidate(candidate);
check("re-syncing the same save changes nothing", again.status === "NO_CHANGE", String(again.status));
check(
  "and writes no second copy of the squad",
  (await db.select().from(players).where(eq(players.careerId, CAREER_ID))).length === 3
);

// ---------------------------------------------------------------------------------------------
console.log("\nthe app's own FC saves are unaffected");
// ---------------------------------------------------------------------------------------------

const SAVE_DIR = path.join(process.cwd(), "data", "saves");
const realSaves = fs
  .readdirSync(SAVE_DIR)
  .filter((name) => /^(CmMgrC|ManagerCareer|Career2)/.test(name))
  .filter((name) => !name.includes("Career2018"));

check("there is a real save to check against", realSaves.length > 0, String(realSaves.length));

for (const name of realSaves) {
  const real = new Uint8Array(fs.readFileSync(path.join(SAVE_DIR, name)));
  const realChoice = chooseGameVersion(listSaveTableIds(real), index);
  check(
    `${name} still identifies as an FC-era save`,
    realChoice?.descriptor.id === "FC26" && realChoice.confident,
    `${realChoice?.descriptor.id} at ${realChoice?.score.toFixed(2)}`
  );
}

console.log(`\n${passed} passed, ${failures.length} failed`);
if (failures.length > 0) {
  console.log("\nfailures:");
  for (const failure of failures) console.log(`  - ${failure}`);
  process.exit(1);
}

}

void main();
